package org.apache.pinot.segment.local.aggregator;

import org.apache.datasketches.theta.Sketch;
import org.apache.datasketches.theta.Sketches;
import org.apache.datasketches.theta.Union;
import org.apache.datasketches.theta.UpdateSketch;
import org.apache.pinot.segment.local.utils.CustomSerDeUtils;
import org.apache.pinot.segment.spi.AggregationFunctionType;
import org.apache.pinot.spi.data.FieldSpec.DataType;
import org.apache.pinot.spi.utils.CommonConstants;


/**
 * Aggregates theta sketches for the star-tree index. The intermediate aggregated value is kept as a
 * {@link Union} so that merges can be applied without re-creating a union on every call. Only when the value needs
 * to be serialized (or a raw {@link Sketch} result is required) is the underlying sketch extracted from the union.
 */
public class DistinctCountThetaSketchValueAggregator implements ValueAggregator<Object, Object> {
  public static final DataType AGGREGATED_VALUE_TYPE = DataType.BYTES;

  public DistinctCountThetaSketchValueAggregator() {
  }

  @Override
  public AggregationFunctionType getAggregationType() {
    return AggregationFunctionType.DISTINCTCOUNTTHETASKETCH;
  }

  @Override
  public DataType getAggregatedValueType() {
    return AGGREGATED_VALUE_TYPE;
  }

  @Override
  public Object getInitialAggregatedValue(Object rawValue) {
    Union union = emptyUnion();
    if (rawValue instanceof byte[]) { // Serialized Sketch
      union.union(deserializeSketch((byte[]) rawValue));
    } else if (rawValue instanceof byte[][]) { // Multiple Serialized Sketches
      byte[][] serializedSketches = (byte[][]) rawValue;
      for (byte[] bytes : serializedSketches) {
        union.union(deserializeSketch(bytes));
      }
    } else {
      union.union(singleItemSketch(rawValue));
    }
    return union;
  }

  @Override
  public Object applyRawValue(Object value, Object rawValue) {
    Union union = extractUnion(value);
    if (rawValue instanceof byte[]) {
      union.union(deserializeSketch((byte[]) rawValue));
    } else {
      union.union(singleItemSketch(rawValue));
    }
    return union;
  }

  @Override
  public Object applyAggregatedValue(Object value, Object aggregatedValue) {
    Union union = extractUnion(value);
    union.union(extractSketch(aggregatedValue));
    return union;
  }

  @Override
  public Object cloneAggregatedValue(Object value) {
    return deserializeAggregatedValue(serializeAggregatedValue(value));
  }

  @Override
  public int getMaxAggregatedValueByteSize() {
    // A union pre-allocates its internal hash table based on the nominal entries, so its current size is a static
    // upper bound for the aggregated value regardless of the data seen.
    return emptyUnion().getCurrentBytes();
  }

  @Override
  public byte[] serializeAggregatedValue(Object value) {
    return CustomSerDeUtils.DATA_SKETCH_THETA_SER_DE.serialize(extractSketch(value));
  }

  @Override
  public Object deserializeAggregatedValue(byte[] bytes) {
    return CustomSerDeUtils.DATA_SKETCH_THETA_SER_DE.deserialize(bytes);
  }

  private Sketch deserializeSketch(byte[] bytes) {
    return CustomSerDeUtils.DATA_SKETCH_THETA_SER_DE.deserialize(bytes);
  }

  // Utility method to create an empty union with the default nominal entries
  private Union emptyUnion() {
    // TODO: Handle configurable nominal entries for StarTreeBuilder
    return Union.builder().setNominalEntries(CommonConstants.Helix.DEFAULT_THETA_SKETCH_NOMINAL_ENTRIES).buildUnion();
  }

  // Reuse the union if the value is already a Union, otherwise wrap the Sketch in a new Union.
  private Union extractUnion(Object value) {
    if (value instanceof Union) {
      return (Union) value;
    }
    Union union = emptyUnion();
    if (value instanceof Sketch) {
      union.union((Sketch) value);
    }
    return union;
  }

  // Extract the underlying sketch, resolving the union result if necessary.
  private Sketch extractSketch(Object value) {
    if (value instanceof Union) {
      return ((Union) value).getResult();
    }
    return (Sketch) value;
  }

  // Utility method to create a theta sketch with one item in it
  private Sketch singleItemSketch(Object rawValue) {
    // TODO: Handle configurable nominal entries for StarTreeBuilder
    UpdateSketch sketch =
        Sketches.updateSketchBuilder().setNominalEntries(CommonConstants.Helix.DEFAULT_THETA_SKETCH_NOMINAL_ENTRIES)
            .build();
    if (rawValue instanceof String) {
      sketch.update((String) rawValue);
    } else if (rawValue instanceof Integer) {
      sketch.update((Integer) rawValue);
    } else if (rawValue instanceof Long) {
      sketch.update((Long) rawValue);
    } else if (rawValue instanceof Double) {
      sketch.update((Double) rawValue);
    } else if (rawValue instanceof Float) {
      sketch.update((Float) rawValue);
    } else if (rawValue instanceof Object[]) {
      addObjectsToSketch((Object[]) rawValue, sketch);
    } else {
      throw new IllegalStateException(
          "Unsupported data type for Theta Sketch aggregation: " + rawValue.getClass().getSimpleName());
    }
    return sketch.compact();
  }

  private void addObjectsToSketch(Object[] rawValues, UpdateSketch updateSketch) {
    if (rawValues instanceof String[]) {
      for (String s : (String[]) rawValues) {
        updateSketch.update(s);
      }
    } else if (rawValues instanceof Integer[]) {
      for (Integer i : (Integer[]) rawValues) {
        updateSketch.update(i);
      }
    } else if (rawValues instanceof Long[]) {
      for (Long l : (Long[]) rawValues) {
        updateSketch.update(l);
      }
    } else if (rawValues instanceof Double[]) {
      for (Double d : (Double[]) rawValues) {
        updateSketch.update(d);
      }
    } else if (rawValues instanceof Float[]) {
      for (Float f : (Float[]) rawValues) {
        updateSketch.update(f);
      }
    } else {
      throw new IllegalStateException(
          "Unsupported data type for Theta Sketch aggregation: " + rawValues.getClass().getSimpleName());
    }
  }
}
