package org.apache.pinot.segment.local.aggregator;

import org.apache.datasketches.tuple.Sketch;
import org.apache.datasketches.tuple.Union;
import org.apache.datasketches.tuple.aninteger.IntegerSummary;
import org.apache.datasketches.tuple.aninteger.IntegerSummarySetOperations;
import org.apache.pinot.segment.local.utils.CustomSerDeUtils;
import org.apache.pinot.segment.spi.AggregationFunctionType;
import org.apache.pinot.spi.data.FieldSpec.DataType;
import org.apache.pinot.spi.utils.CommonConstants;


/**
 * Aggregates integer tuple sketches for the star-tree index. The intermediate aggregated value is kept as a
 * {@link Union} so that merges can be applied without re-creating a union on every call. Only when the value needs
 * to be serialized (or a raw {@link Sketch} result is required) is the underlying sketch extracted from the union.
 */
@SuppressWarnings({"rawtypes", "unchecked"})
public class IntegerTupleSketchValueAggregator implements ValueAggregator<byte[], Object> {
  public static final DataType AGGREGATED_VALUE_TYPE = DataType.BYTES;

  private final int _nominalEntries;
  private final IntegerSummary.Mode _mode;

  public IntegerTupleSketchValueAggregator(IntegerSummary.Mode mode) {
    _mode = mode;
    _nominalEntries = 1 << CommonConstants.Helix.DEFAULT_TUPLE_SKETCH_LGK;
  }

  @Override
  public AggregationFunctionType getAggregationType() {
    return AggregationFunctionType.DISTINCTCOUNTTUPLESKETCH;
  }

  @Override
  public DataType getAggregatedValueType() {
    return AGGREGATED_VALUE_TYPE;
  }

  @Override
  public Object getInitialAggregatedValue(byte[] rawValue) {
    Union<IntegerSummary> union = emptyUnion();
    if (rawValue != null) {
      union.union(deserializeSketch(rawValue));
    }
    return union;
  }

  @Override
  public Object applyRawValue(Object value, byte[] rawValue) {
    Union<IntegerSummary> union = extractUnion(value);
    union.union(deserializeSketch(rawValue));
    return union;
  }

  @Override
  public Object applyAggregatedValue(Object value, Object aggregatedValue) {
    Union<IntegerSummary> union = extractUnion(value);
    union.union(extractSketch(aggregatedValue));
    return union;
  }

  @Override
  public Object cloneAggregatedValue(Object value) {
    return deserializeAggregatedValue(serializeAggregatedValue(value));
  }

  @Override
  public int getMaxAggregatedValueByteSize() {
    // Assumes the worst case of the sketch in estimation mode, which requires storing theta and count on top of the
    // hash (Long.BYTES) and IntegerSummary (Integer.BYTES) for each nominal entry.
    if (_nominalEntries == 0) {
      return 8;
    }
    if (_nominalEntries == 1) {
      return 16;
    }
    return (_nominalEntries * (Long.BYTES + Integer.BYTES)) + 24;
  }

  @Override
  public byte[] serializeAggregatedValue(Object value) {
    return CustomSerDeUtils.DATA_SKETCH_INT_TUPLE_SER_DE.serialize(extractSketch(value));
  }

  @Override
  public Object deserializeAggregatedValue(byte[] bytes) {
    return CustomSerDeUtils.DATA_SKETCH_INT_TUPLE_SER_DE.deserialize(bytes);
  }

  private Sketch<IntegerSummary> deserializeSketch(byte[] bytes) {
    return CustomSerDeUtils.DATA_SKETCH_INT_TUPLE_SER_DE.deserialize(bytes);
  }

  // Utility method to create an empty union with the configured nominal entries
  private Union<IntegerSummary> emptyUnion() {
    return new Union<>(_nominalEntries, new IntegerSummarySetOperations(_mode, _mode));
  }

  // Reuse the union if the value is already a Union, otherwise wrap the Sketch in a new Union.
  private Union<IntegerSummary> extractUnion(Object value) {
    if (value instanceof Union) {
      return (Union<IntegerSummary>) value;
    }
    Union<IntegerSummary> union = emptyUnion();
    if (value instanceof Sketch) {
      union.union((Sketch<IntegerSummary>) value);
    }
    return union;
  }

  // Extract the underlying sketch, resolving the union result if necessary.
  private Sketch<IntegerSummary> extractSketch(Object value) {
    if (value instanceof Union) {
      return ((Union<IntegerSummary>) value).getResult();
    }
    return (Sketch<IntegerSummary>) value;
  }
}
